#!/usr/bin/env python3
"""Generate the CACHE-13 threats-covered handoff from observed suite results."""
from collections import Counter
import json
from pathlib import Path
import sys


def render(rows):
    if not rows or any(r["outcome"] != r["expected"] for r in rows):
        raise ValueError("handoff requires nonempty results with every outcome expected")
    lines = [
        "<!-- Generated by python3 scripts/drill/cache-security/handoff.py; do not edit. -->",
        "# Cache, artifact and release threats covered",
        "",
        "Source: `matrix.yaml` and `testdata/results.json`. Audit exceptions remain explicit in the matrix.",
        "",
        "| Threat | Cases | Carriers | Observed outcomes | Recorded audit exceptions |",
        "| --- | ---: | --- | --- | ---: |",
    ]
    for threat in sorted({r["threat"] for r in rows}):
        cases = [r for r in rows if r["threat"] == threat]
        carriers = ", ".join(sorted({r["carrier"] for r in cases}))
        outcomes = ", ".join(f"{name}: {n}" for name, n in sorted(Counter(r["outcome"] for r in cases).items()))
        missing = sum(r["audit"] == "none" for r in cases)
        lines.append(f"| {threat} | {len(cases)} | {carriers} | {outcomes} | {missing} |")
    lines.extend([
        "",
        "Production findings: HQ `quality/debt.yaml` D-1450 through D-1454. The signed-remote positive case exercises the release gate and guard; dispatcher admission remains covered by D-1454.",
        "",
        "Merge requires adversarial and security reviews. Passing expected outcomes does not close the recorded production findings.",
    ])
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    root = Path(__file__).resolve().parents[3]
    source = root / "free/ci/test/cachesec/testdata/results.json"
    try:
        sys.stdout.write(render(json.loads(source.read_text())))
    except (OSError, ValueError, KeyError) as exc:
        sys.exit(f"cache-security handoff: {exc}")
